import sys

def calculate(a: int, b: int) -> int:
    return a + b

def calculate(a: float, b: float) -> float:
    return a + b

def calculate(a: str, b: str) -> str:
    return a + b

def main():
    data_type = input().strip()
    val1 = input().strip()
    val2 = input().strip()

    if data_type == 'int':
        a = int(val1)
        b = int(val2)
        result = calculate(a, b)
        print(result)
    elif data_type == 'float':
        a = float(val1)
        b = float(val2)
        result = calculate(a, b)
        print(result)
    elif data_type == 'string':
        result = calculate(val1, val2)
        print(result)

if __name__ == "__main__":
    main()
